# SPDX-License-Identifier: MIT
# Print the descriptor of the first fdatasync in a system-seccomp.py notify
# log (the temp file of an atomic write); print nothing if there is none.
import json, sys
for line in open(sys.argv[1]):
    if line.strip():
        r = json.loads(line)
        if r["syscall"] == "fdatasync":
            print(r["arg0"])
            break
